def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    aggressive = 0
    rich_alive = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) > 700:
                rich_alive += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 80:
                    aggressive += 1

    if not alive:
        return max(0.0, min(budget, 18.0))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity_units = supply / float(WATER_REQ)
    very_tight = scarcity_units < 1.45
    tight = scarcity_units < 1.7

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water >= 2:
        urgency += 4
    elif no_water >= 1:
        urgency += 2
    if day >= 8:
        urgency += 1
    if very_tight:
        urgency += 2
    elif tight:
        urgency += 1

    if urgency >= 7:
        target = max(92.0, max_prev + 4.0)
    elif urgency >= 5:
        target = max(76.0, max_prev * 0.92 + 3.0)
    elif urgency >= 3:
        target = max(52.0, avg_prev * 0.78 + 2.0)
    else:
        if very_tight:
            target = 41.0
        elif tight:
            target = 30.0
        else:
            target = 22.0

    if max_prev >= 120 and urgency <= 3:
        target = min(target, 34.0)
    if aggressive >= 2 and urgency <= 4:
        target = min(target, 36.0)
    if rich_alive >= 2 and urgency <= 2:
        target = min(target, 28.0)

    if hp <= 3 or no_water >= 2:
        target = max(target, 88.0)
    elif hp <= 5 or no_water >= 1:
        target = max(target, 64.0)

    reserve_floor = 0.0
    if day <= 6:
        reserve_floor = DAILY_SALARY * (10 - day) * 0.18
    elif day <= 8:
        reserve_floor = DAILY_SALARY * (10 - day) * 0.1

    spend_cap = max(0.0, budget - reserve_floor)
    if hp <= 3 or no_water >= 2:
        spend_cap = budget

    bid = min(target, spend_cap)
    if bid < 0:
        bid = 0.0
    if budget <= 25:
        bid = budget

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return float(min(my_status['budget'], 10.0))
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0
    if my_status['hp'] <= 4:
        bid = min(my_status['budget'], avg_prev_bid * 1.2)
    else:
        bid = min(my_status['budget'], avg_prev_bid * 0.95)
    return float(max(1.0, bid))
